WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/26.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/26.0/apex.js")} 

var user = sforce.connection.query("Select isActive,Commission_ID__c from User where Id = '{!Opportunity.OwnerId}' "); 
var opps = sforce.connection.query("Select Amount,Total_Sales_Billing_Estimate__c from Opportunity where Id = '{!Opportunity.Id}' ");

if(opps.records.Amount >= 25000 &&
 opps.records.Total_Sales_Billing_Estimate__c <=0 &&
 (opps.records.Type ==='New Deal' || opps.records.Type === 'Up-Sell/Lift')
){ 
 alert("Please add sales Billing Forecast record"); 
 }else{
if ( "{!Opportunity.Type}" === "Renewal" ) 
{ 
window.location.href="/apex/renewalOppWizard2_step1?oppId={!Opportunity.Id}&accId={!Opportunity.AccountId}&imga={!Opportunity.IMGA_Name__c}"; 

//alert("Renewal Opportunities cannot go through NCSP process."); 
} 
else if( user.records.IsActive == 'false' ) 
{ 
alert('Only opportunities with active users may use the NCSP wizard'); 
} 
else if(user.records.Commission_ID__c == null || user.records.Commission_ID__c == ' ') 
{ 
alert("Your Commission ID is missing from your Sales Rep profile, and is needed to complete an NCSP form. You may obtain your Commission ID from a member of the Commissions Accounting team in Royersford, PA. Upon receipt, you must enter this ID in your SFDC Sales Rep user profile and then you may continue the submission of your NCSP form.") 
} 
else 
{ 
if('{!Opportunity.StageName}' === '5 - Signed/PO in' ) 
{ 
if( '{!Opportunity.Type}' === 'Up-Sell/Lift' ) 
{ 
window.location.href="/apex/NCSPSell_LiftWizard_CompletedOrder?Id={!Opportunity.Id}"; 
} 
else 
{ 
window.location.href="/apex/NCSPWizard_Step1?oppId={!Opportunity.Id}"; 
} 
}else 
{ 
alert("OPPORTUNITY MUST BE AT Stage '5 – Signed/PO In' BEFORE SUBMITTING TO NEW CUSTOMER IMPLEMENTATIONS TEAM"); 
} 
}
}
